export type DeviceChoiceGridConfig = typeof defaultDeviceChoiceGridConfig;

export function mergeDeviceChoiceGridConfig(
  base: DeviceChoiceGridConfig,
  override?: DeepPartial<DeviceChoiceGridConfig>
): DeviceChoiceGridConfig {
  return {
    ...base,
    ...override,
    preview: { ...base.preview, ...override?.preview },
    svg: { ...base.svg, ...override?.svg },
    debug: { ...base.debug, ...override?.debug },
    ids: { ...base.ids, ...override?.ids },
    statusOrder: { ...base.statusOrder, ...override?.statusOrder },
    layout: { ...base.layout, ...override?.layout },
    radius: { ...base.radius, ...override?.radius },
    stroke: { ...base.stroke, ...override?.stroke },
    connector: { ...base.connector, ...override?.connector },
    text: { ...base.text, ...override?.text },
    colors: { ...base.colors, ...override?.colors },
    effects: { ...base.effects, ...override?.effects },
    opacity: { ...base.opacity, ...override?.opacity },
    transition: { ...base.transition, ...override?.transition },
  } as DeviceChoiceGridConfig;
}
